#include "entity.h"
#include "level.h"

#include <SDL.h>
#include <stdlib.h>
#include <string.h>

// Most of this document was generated by copilot turning my player code into entity universal code

Animation* Entity_GetCurrentAnimation(Entity *e)
{
	if (!e) return NULL;

	// Prefer attack-stage animation when the entity is in an attack.
	if (e->isAttacking && e->currentAttackIndex >= 0 && e->currentAttackIndex < e->anims.attackCount) {
		AttackDef *attack = &e->anims.attacks[e->currentAttackIndex];
		if (attack && e->currentAttackStage >= 0 && e->currentAttackStage < attack->stageCount) {
			AttackStage *stage = &attack->stages[e->currentAttackStage];
			if (stage->animation) return stage->animation;
		}
	}

	// Fallback to normal animation index
	if (!e->anims.animations || e->currentAnimIndex < 0 || e->currentAnimIndex >= e->anims.animCount) return NULL;
	return &e->anims.animations[e->currentAnimIndex];
}

void Entity_UpdatePhysics(Entity *e, float dt, struct Level *lvl)
{
	if (!e || !lvl) return;

	// Horizontal movement based on flags in PhysicsBody
	float accel = e->body.acceleration;
	float decel = e->body.deceleration;

	if (e->body.isMovingRight) {
		e->body.velocity_x += accel * dt;
	} else if (e->body.isMovingLeft) {
		e->body.velocity_x -= accel * dt;
	} else {
		if (e->body.velocity_x > 0) {
			e->body.velocity_x -= decel * dt;
			if (e->body.velocity_x < 0) e->body.velocity_x = 0;
		} else if (e->body.velocity_x < 0) {
			e->body.velocity_x += decel * dt;
			if (e->body.velocity_x > 0) e->body.velocity_x = 0;
		}
	}

	// Clamp maximum horizontal speed by runSpeed
	if (e->body.velocity_x > e->body.runSpeed) e->body.velocity_x = e->body.runSpeed;
	if (e->body.velocity_x < -e->body.runSpeed) e->body.velocity_x = -e->body.runSpeed;

	// Facing
	if (e->body.isMovingLeft) e->body.flip = SDL_FLIP_HORIZONTAL;
	if (e->body.isMovingRight) e->body.flip = SDL_FLIP_NONE;

	// Gravity
	e->body.velocity_y += e->body.gravity * dt;
	if (e->body.velocity_y > e->body.maxFallSpeed) e->body.velocity_y = e->body.maxFallSpeed;

	// Integrate + collide (X then Y)
	e->body.x += e->body.velocity_x * dt;
	checkEntityTileCollisionsX(&e->body, lvl, dt);

	e->body.y += e->body.velocity_y * dt;
	checkEntityTileCollisionsY(&e->body, lvl, dt);
}

void Entity_UpdateAnimation(Entity *e, float dt)
{
	if (!e) return;
	Animation *anim = Entity_GetCurrentAnimation(e);
	if (!anim) return;

	e->frameTimer += dt;
	if (e->frameTimer >= anim->frameDuration) {
		e->frameTimer -= anim->frameDuration;
		e->currentFrame++;

		if (e->isAttacking && e->currentAttackIndex >= 0 && e->currentAttackIndex < e->anims.attackCount) {
			AttackDef *attack = &e->anims.attacks[e->currentAttackIndex];
			if (e->currentAttackStage >= 0 && e->currentAttackStage < attack->stageCount) {
				AttackStage *stage = &attack->stages[e->currentAttackStage];
				if (e->currentFrame >= stage->animation->frameCount) {
					// Stage finished: generic behavior is to end attack. Specific chaining belongs to caller.
					e->isAttacking = false;
					e->currentAttackIndex = -1;
					e->currentAttackStage = 0;
					e->hitboxActive = false;
					e->canBeInterrupted = true;

				}
			}
		} else {
			if (e->currentFrame >= anim->frameCount) {
				e->currentFrame = anim->loop ? 0 : (anim->frameCount > 0 ? anim->frameCount - 1 : 0);
			}
		}
	}
}

int Entity_FindAnimation(const Entity* e, const char* name)
{
	if (!e || !name) return -1;

	// Defensive: make sure anims array is valid
	if (e->anims.animCount <= 0 || !e->anims.animations) return -1;

	for (int i = 0; i < e->anims.animCount; i++) {
		const Animation* anim = &e->anims.animations[i];
		if (anim && anim->name && strcmp(anim->name, name) == 0) {
			return i;
		}
	}
	return -1;
}

int Entity_FindAttack(const Entity *e, const char *name)
{
	if (!e || !name) return -1;
	for (int i = 0; i < e->anims.attackCount; i++) {
		if (e->anims.attacks[i].name && strcmp(e->anims.attacks[i].name, name) == 0) return i;
	}
	return -1;
}

bool Entity_PlayAnimation(Entity *e, const char *name)
{
	if (!e || !name) return false;
	int idx = Entity_FindAnimation(e, name);
	if (idx < 0 || idx == e->currentAnimIndex) return false;
	e->currentAnimIndex = idx;
	e->currentFrame = 0;
	e->frameTimer = 0.0f;
	Animation *anim = &e->anims.animations[idx];
	e->canBeInterrupted = anim->canBeInterrupted;
	e->invulnerable = anim->invulnerable;
	return true;
}

void Entity_StartAttackStage(Entity* e, int attackIndex, int stageIdx)
{
	if (!e) return;
	if (!e->anims.attacks) return;
	if (attackIndex < 0 || attackIndex >= e->anims.attackCount) return;

	AttackDef* attack = &e->anims.attacks[attackIndex];
	if (stageIdx < 0 || stageIdx >= attack->stageCount) return;

	// runtime state
	e->currentAttackIndex = attackIndex;
	e->currentAttackStage = stageIdx;

	AttackStage* stage = &attack->stages[stageIdx];
	Animation* anim = stage->animation;
	if (!anim) return;

	// Reset animation index so Entity_GetCurrentAnimation favors the attack stage
	e->currentAnimIndex = -1;
	e->currentFrame = 0;
	e->frameTimer = 0.0f;

	// Set the attack timer to the animation length (frameDuration * frameCount)
	e->attackTimer = anim->frameDuration * (anim->frameCount > 0 ? anim->frameCount : 1);

	// Copy hitbox blueprint
	e->activeHitbox = stage->hitbox;
	e->hitboxActive = false;

	// Lock interruption according to the animation
	e->canBeInterrupted = anim->canBeInterrupted;
}

void Entity_UpdateCollisionBox(Entity* e, struct Level* lvl) {
	if (!e) return;

	Animation* anim = Entity_GetCurrentAnimation(e);
	if (!anim) return;

	// Clamp frame index before indexing
	if (e->currentFrame < 0) e->currentFrame = 0;
	if (anim->frameCount <= 0) return;
	if (e->currentFrame >= anim->frameCount) {
		e->currentFrame = anim->frameCount - 1;
	}

	// Safe collision profile
	CollisionProfile defaultProf = { 1.0f, 1.0f, 0.0f, 0.0f };
	CollisionProfile* profile = anim->collisionProfile
		? anim->collisionProfile
		: (e->collisionProfiles ? &e->collisionProfiles[0] : &defaultProf);

	SDL_Rect frame = anim->frames[e->currentFrame];

	// Resize collision rect
	e->body.collisionRect.w = (int)(frame.w * e->spriteScale * profile->widthScale);
	e->body.collisionRect.h = (int)(frame.h * e->spriteScale * profile->heightScale);

	// Position collision rect
	e->body.collisionRect.x = (int)(e->body.x);
	e->body.collisionRect.y = (int)(e->body.y);

}

void Entity_UpdateAttackHitbox(Entity *e)
{
	if (!e) return;
	if (!e->isAttacking) {
		e->hitboxActive = false;
		return;
	}
	if (e->currentAttackIndex < 0 || e->currentAttackIndex >= e->anims.attackCount) return;

	AttackDef *attack = &e->anims.attacks[e->currentAttackIndex];
	int stageIdx = e->currentAttackStage;
	if (stageIdx < 0 || stageIdx >= attack->stageCount) return;

	AttackStage *stage = &attack->stages[stageIdx];
	Animation *anim = stage->animation;
	if (!anim) return;

	for (int i = 0; i < anim->eventCount; i++) {
		AnimationEvent *evt = &anim->events[i];
		if (evt->frameIndex == e->currentFrame && evt->type && strcmp(evt->type, "hitbox") == 0) {
			int baseX = e->body.collisionRect.x;
			int baseY = e->body.collisionRect.y;

			int offsetX = stage->hitbox.offsetX;
			if (e->body.flip == SDL_FLIP_HORIZONTAL)
			{
				offsetX *= -1;
			}
			int hitboxX = baseX + offsetX;
			int hitboxY = baseY + stage->hitbox.offsetY;

			e->activeHitbox.x = hitboxX;
			e->activeHitbox.y = hitboxY;
			e->activeHitbox.w = stage->hitbox.w;
			e->activeHitbox.h = stage->hitbox.h;
			e->activeHitbox.offsetX = stage->hitbox.offsetX;
			e->activeHitbox.offsetY = stage->hitbox.offsetY;
			e->hitboxActive = true;
			break;
		}
	}

	if (anim && e->currentFrame >= anim->frameCount) {
		e->hitboxActive = false;
	}
}

void Entity_Render(const Entity* entity, SDL_Renderer* renderer, const Camera* camera, bool debug)
{
	if (!entity || !renderer) return;

	// get current animation
	const Animation* anim = Entity_GetCurrentAnimation((Entity*)entity);
	if (!anim) return;

	// safety for frame index
	if (entity->currentFrame < 0 || entity->currentFrame >= anim->frameCount) return;

	// sheet must be valid
	if (!entity->sheets) return;
	if (anim->sheetIndex < 0 || anim->sheetIndex >= entity->sheetCount) return;
	const SpriteSheet* sheet = &entity->sheets[anim->sheetIndex];
	SDL_Rect frame = anim->frames[entity->currentFrame];

	SDL_Rect destRect;
	destRect.w = (int)(frame.w * entity->spriteScale);
	destRect.h = (int)(frame.h * entity->spriteScale);

	// Using collisionRect as anchor 
	destRect.x = (int)(entity->body.collisionRect.x - camera->x + (entity->body.collisionRect.w - destRect.w) / 2);
	destRect.y = (int)(entity->body.collisionRect.y - camera->y + entity->body.collisionRect.h - destRect.h);

	// apply collision profile offsets if present
	const CollisionProfile* profile = anim->collisionProfile
		? anim->collisionProfile
		: (entity->collisionProfiles ? &entity->collisionProfiles[0] : NULL);
	if (profile) {
		int offsetX = (int)(profile->offsetX * entity->spriteScale);
		destRect.x += (entity->body.flip == SDL_FLIP_NONE) ? -offsetX : offsetX;
		destRect.y += (int)(profile->offsetY * entity->spriteScale);
	}

	SDL_RenderCopyEx(renderer, sheet->texture, &frame, &destRect, 0, NULL, entity->body.flip);

	// debug draw hitbox & collision
	if (debug) {
		// collision rect
		SDL_SetRenderDrawColor(renderer, 0, 255, 0, 150);
		SDL_Rect collRect = {
			entity->body.collisionRect.x - camera->x,
			entity->body.collisionRect.y - camera->y,
			entity->body.collisionRect.w,
			entity->body.collisionRect.h
		};
		SDL_RenderDrawRect(renderer, &collRect);

		// active hitbox
		if (entity->hitboxActive) {
			SDL_SetRenderDrawColor(renderer, 255, 0, 0, 150);
			SDL_Rect hitRect = {
				entity->activeHitbox.x - camera->x,
				entity->activeHitbox.y - camera->y,
				entity->activeHitbox.w,
				entity->activeHitbox.h
			};
			SDL_RenderDrawRect(renderer, &hitRect);
		}
	}
	HealthBar_Render(&entity->healthBar, renderer, camera);
}

void Entity_Destroy(Entity *e)
{
	if (!e) return;

	HealthBar_Free(&e->healthBar);

	// Sheets
	if (e->sheets) {
		for (int i = 0; i < e->sheetCount; i++) {
			if (e->sheets[i].name) free(e->sheets[i].name);
			if (e->sheets[i].texture) SDL_DestroyTexture(e->sheets[i].texture);
		}
		free(e->sheets);
		e->sheets = NULL;
	}

	// Animations
	if (e->anims.animations) {
		for (int i = 0; i < e->anims.animCount; i++) {
			Animation *a = &e->anims.animations[i];
			if (a->name) free(a->name);
			if (a->frames) free(a->frames);
			if (a->events) {
				for (int j = 0; j < a->eventCount; j++) {
					if (a->events[j].type) free(a->events[j].type);
					if (a->events[j].value) free(a->events[j].value);
				}
				free(a->events);
			}
			if (a->collisionProfile) free(a->collisionProfile);
		}
		free(e->anims.animations);
		e->anims.animations = NULL;
		e->anims.animCount = 0;
	}

	// Attacks
	if (e->anims.attacks) {
		for (int i = 0; i < e->anims.attackCount; i++) {
			AttackDef *ad = &e->anims.attacks[i];
			if (ad->name) free(ad->name);
			if (ad->type) free(ad->type);
			if (ad->stages) {
				for (int s = 0; s < ad->stageCount; s++) {
					AttackStage *st = &ad->stages[s];
					if (st->projectileName) free(st->projectileName);
					// If projectile pointers.
				}
				free(ad->stages);
			}
		}
		free(e->anims.attacks);
		e->anims.attacks = NULL;
		e->anims.attackCount = 0;
	}

	// Collision profiles (if dynamically allocated outside animations)
	if (e->collisionProfiles) {
		free(e->collisionProfiles);
		e->collisionProfiles = NULL;
		e->profileCount = 0;
	}
}


